using FatturaFacile.Application.Common.Security;
using FatturaFacile.Application.Dss;
using FatturaFacile.Domain.Enums;
using MediatR;

namespace FatturaFacile.Application.Features.Dss;

/// <summary>
/// Query for the localized Executive Board Briefing Pack of a filter, generated by the web-api (online only).
/// </summary>
/// <param name="Filter">The filter.</param>
/// <param name="Format">pdf or xlsx.</param>
/// <param name="Locale">The language of the document (it-CH, de-CH, fr-CH, en or it-IT).</param>
public sealed record ExportDssBoardPackQuery(DssFilter Filter, string Format, string Locale) : IRequest<DssBoardPack>, IAuthorizedRequest
{
    /// <inheritdoc/>
    public Permission RequiredPermission => Permission.AccountingRead;
}
